pub fn format_f32(v: f32) -> String {
    if v.is_nan() { return if v.is_sign_negative() { "-nan".into() } else { "nan".into() }; }
    if v.is_infinite() { return if v < 0.0 { "-inf".into() } else { "inf".into() }; }
    // %g with precision 6
    const P: i32 = 6;
    if v == 0.0 {
        return if v.is_sign_negative() { "-0".into() } else { "0".into() };
    }
    // get decimal exponent
    let sci = format!("{:.*e}", (P - 1) as usize, v); // e.g. "-3.33333e1"
    let epos = sci.find('e').unwrap();
    let exp: i32 = sci[epos + 1..].parse().unwrap();
    let mantissa = &sci[..epos];
    if exp < -4 || exp >= P {
        // scientific: strip trailing zeros in mantissa
        let m = strip_zeros(mantissa);
        format!("{}e{}{:02}", m, if exp < 0 { '-' } else { '+' }, exp.abs())
    } else {
        let prec = (P - 1 - exp) as usize;
        let fixed = format!("{:.*}", prec, v);
        strip_zeros(&fixed)
    }
}

fn strip_zeros(s: &str) -> String {
    if s.contains('.') {
        let t = s.trim_end_matches('0');
        let t = t.strip_suffix('.').unwrap_or(t);
        t.to_string()
    } else { s.to_string() }
}
```

