pub mod hsl;
pub mod converter;
pub mod stof;
pub mod cformat;

/// HSL color, mirroring `ColorSpace::HSL` from the C++ library.
#[derive(Clone, Copy, Debug)]
pub struct Hsl {
    pub h: f32,
    #[allow(dead_code)]
    pub s: f32,
    #[allow(dead_code)]
    pub l: f32,
}

impl Hsl {
    pub fn new(h: f32, s: f32, l: f32) -> Self {
        Hsl { h, s, l }
    }
}

use crate::color::hsl::Hsl;

/// Mirrors `ColorSpace::ColorConverter`.
pub struct ColorConverter;

impl ColorConverter {
    /// Smallest difference between two hues.
    ///
    /// Matches the C++ behavior: absolute hue difference, folded once
    /// past 180 degrees (single conditional, not a loop — so hues far
    /// outside [0, 360] can yield results outside [-180, 180]).
    pub fn hue_difference(a: &Hsl, b: &Hsl) -> f32 {
        let mut d = (a.h - b.h).abs();
        if d > 180.0 {
            d = 360.0 - d;
        }
        d
    }
}

/// Reimplements C++ `std::stof` semantics: leading whitespace is skipped,
/// the longest valid float prefix is parsed (trailing garbage ignored),
/// `inf`/`infinity`/`nan` are accepted, and invalid or out-of-range input
/// aborts the process the way an uncaught C++ exception does.

pub fn stof(s: &str) -> f32 {
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() && (bytes[i] as char).is_whitespace() {
        i += 1;
    }
    let start = i;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        i += 1;
    }

    let lower = s[i..].to_ascii_lowercase();
    if lower.starts_with("infinity") || lower.starts_with("inf") {
        return if s.as_bytes()[start] == b'-' {
            f32::NEG_INFINITY
        } else {
            f32::INFINITY
        };
    }
    if lower.starts_with("nan") {
        return f32::NAN;
    }

    let mut j = i;
    let mut saw_digit = false;
    while j < bytes.len() && bytes[j].is_ascii_digit() {
        j += 1;
        saw_digit = true;
    }
    if j < bytes.len() && bytes[j] == b'.' {
        j += 1;
        while j < bytes.len() && bytes[j].is_ascii_digit() {
            j += 1;
            saw_digit = true;
        }
    }
    if !saw_digit {
        invalid_argument();
    }
    let mut end = j;
    if j < bytes.len() && (bytes[j] == b'e' || bytes[j] == b'E') {
        let mut k = j + 1;
        if k < bytes.len() && (bytes[k] == b'+' || bytes[k] == b'-') {
            k += 1;
        }
        let digit_start = k;
        while k < bytes.len() && bytes[k].is_ascii_digit() {
            k += 1;
        }
        if k > digit_start {
            end = k;
        }
    }

    let v: f32 = match s[start..end].parse() {
        Ok(v) => v,
        Err(_) => invalid_argument(),
    };
    // strtof sets ERANGE on overflow (inf) and underflow (subnormal/zero
    // from a nonzero literal), which makes std::stof throw out_of_range.
    if v.is_infinite() {
        out_of_range();
    }
    v
}

fn invalid_argument() -> ! {
    eprintln!("terminate called after throwing an instance of 'std::invalid_argument'");
    eprintln!("  what():  stof");
    std::process::abort();
}

fn out_of_range() -> ! {
    eprintln!("terminate called after throwing an instance of 'std::out_of_range'");
    eprintln!("  what():  stof");
    std::process::abort();
}

/// Formats an `f32` exactly like C++ `std::cout << float` with default
/// flags: `%g` with 6 significant digits, trailing zeros stripped,
/// scientific notation when the decimal exponent is < -4 or >= 6.

pub fn format_f32(v: f32) -> String {
    if v.is_nan() {
        return if v.is_sign_negative() { "-nan".into() } else { "nan".into() };
    }
    if v.is_infinite() {
        return if v < 0.0 { "-inf".into() } else { "inf".into() };
    }
    if v == 0.0 {
        return if v.is_sign_negative() { "-0".into() } else { "0".into() };
    }

    const P: i32 = 6;
    // Round to P significant digits first; the rounded value determines
    // the decimal exponent used to pick fixed vs. scientific notation.
    let sci = format!("{:.*e}", (P - 1) as usize, v);
    let epos = sci.find('e').unwrap();
    let exp: i32 = sci[epos + 1..].parse().unwrap();

    if exp < -4 || exp >= P {
        let mantissa = strip_zeros(&sci[..epos]);
        format!("{}e{}{:02}", mantissa, if exp < 0 { '-' } else { '+' }, exp.abs())
    } else {
        let prec = (P - 1 - exp) as usize;
        strip_zeros(&format!("{:.*}", prec, v))
    }
}

fn strip_zeros(s: &str) -> String {
    if s.contains('.') {
        let t = s.trim_end_matches('0');
        t.strip_suffix('.').unwrap_or(t).to_string()
    } else {
        s.to_string()
    }
}

